{
  "schema_version": 1,
  "name": "pragmatic_reference_scene_battery",
  "summary": "Referent choice across multi-object scenes with and without informative messages.",
  "charter": {
    "question": "How do listeners combine recursive pragmatic reasoning about alternative utterances with perceptual singleton pop-out, relational distinctiveness, and feature complexity across diverse scene sizes?"
  },
  "instructions": {
    "welcome": "Welcome! In this short study, you will see groups of simple drawings and figure out which one a speaker is talking about.",
    "task": "On each page, you will see several objects (such as robots or houses) that can have different extra parts. Usually, a speaker who sees the exact same screen says a single word to help you pick out one specific object. Click on the object you think the speaker means. On some pages, you will not hear which word the speaker said; on those pages, click on the object you think the speaker is most likely to talk about.",
    "comprehension_checks": [
      {
        "question": "What is your task when the speaker says a word?",
        "options": [
          "Click on the object you think the speaker is referring to.",
          "Click on every object that has the named part.",
          "Click on the object with the most parts."
        ],
        "correct": 0
      },
      {
        "question": "Does the speaker see the same objects on the screen as you do?",
        "options": [
          "Yes, the speaker sees the exact same group of objects.",
          "No, the speaker only sees one object.",
          "No, the speaker sees a different set of objects."
        ],
        "correct": 0
      }
    ]
  },
